def deep_flatten(lst):
  result = []
  for item in lst:
  if isinstance(item, list):
  result.extend(deep_flatten(item))
  else:
  result.append(item)
  return result

 print(deep_flatten([1, [2, [3, [4]], 5]]))

 # Output:
 # [1, 2, 3, 4, 5]

def unique_chars(s):
  seen = set()
  result = []
  for ch in s:
  if ch not in seen:
  seen.add(ch)
  result.append(ch)
  return ''.join(result)

 print(unique_chars('programming'))

 # Output:
 # progamin

def is_leap(year):
  return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

 for y in [2000, 1900, 2024, 2023]:
  print(f'{y}: {is_leap(y)}')

 # Output:
 # 2000: True
 # 1900: False
 # 2024: True
 # 2023: False

def pairs_to_dict(pairs):
  return {k: v for k, v in pairs}

 pairs = [('name', 'Bob'), ('age', 25), ('city', 'Mumbai')]
 print(pairs_to_dict(pairs))

 # Output:
 # {'name': 'Bob', 'age': 25, 'city': 'Mumbai'}

def common_elements(lst1, lst2):
  return list(set(lst1) & set(lst2))

