grade_book = {}

 def add_grade(name, score):
  grade_book[name] = score

 def average_grade():
  return sum(grade_book.values()) / len(grade_book)

 add_grade('Alice', 88)
 add_grade('Bob', 92)
 add_grade('Charlie', 75)
 print(f'Average: {average_grade():.2f}')

 # Output:
 # Average: 85.00

def count_case(s):
  upper = sum(1 for c in s if c.isupper())
  lower = sum(1 for c in s if c.islower())
  return {'uppercase': upper, 'lowercase': lower}

 print(count_case('Hello World from Python'))

 # Output:
 # {'uppercase': 3, 'lowercase': 16}

def caesar_cipher(text, k):
  result = ''
  for ch in text:
  if ch.isalpha():
  base = ord('A') if ch.isupper() else ord('a')
  result += chr((ord(ch) - base + k) % 26 + base)
  else:
  result += ch
  return result

 print(caesar_cipher('Hello World', 3))

 # Output:
 # Khoor Zruog

import time

 def timer(func):
  def wrapper(*args, **kwargs):
  start = time.time()
  result = func(*args, **kwargs)
  end = time.time()
  print(f'{func.__name__} took {end - start:.4f} seconds')
  return result
  return wrapper

 @timer
 def slow_sum(n):
  return sum(range(n))

 slow_sum(1000000)

 # Output:
 # slow_sum took 0.04XX seconds

def selection_sort(arr):
  for i in range(len(arr)):
  min_idx = i
  for j in range(i+1, len(arr)):
  if arr[j] < arr[min_idx]:
  min_idx = j
  arr[i], arr[min_idx] = arr[min_idx], arr[i]
  return arr

 print(selection_sort([64, 25, 12, 22, 11]))

 # Output:
 # [11, 12, 22, 25, 64]
